const extractedData = []; // Initialize an empty array to store the extracted data
for (const item of items) { 
  const results = item.json.result; // Access the 'result' array from the input item's JSON. Assumes input is array of one element

  if (results && Array.isArray(results)) { // Check if results exist and is an array
    for (const resultItem of results) { // Iterate over each object in the 'result' array
      const extractedObject = {}; // Create a new object for each extracted item

      extractedObject.keyword = resultItem.keyword;
      extractedObject.competition_index = resultItem.competition_index;
      extractedObject.avg_monthly_searches = resultItem.avg_monthly_searches;
      extractedObject.competition_value = resultItem.competition_value;
      extractedObject["Low CPC"] = resultItem["Low CPC"]; // Use bracket notation for keys with spaces
      extractedObject["High CPC"] = resultItem["High CPC"]; // Use bracket notation for keys with spaces

      extractedData.push({ json: extractedObject }); 
    }
  }
}

return extractedData;
